package export_ohrats_rc_scheduler_evaluator

import (
	witTypes "go.bytecodealliance.org/pkg/wit/types"
	types "wit_component/ohrats_rc_scheduler_types"
	sched "wit_component/schedule"
)

func NextOccurrence(definition types.Definition, afterUnixMs uint64, lastOccurrenceId witTypes.Option[string]) witTypes.Result[witTypes.Option[types.Occurrence], string] {
	if !definition.Enabled {
		return noOccurrence()
	}
	if definition.ExpiresAtMs.IsSome() && definition.ExpiresAtMs.Some() <= afterUnixMs {
		return noOccurrence()
	}
	var lastOccurrenceID *string
	if lastOccurrenceId.IsSome() {
		value := lastOccurrenceId.Some()
		lastOccurrenceID = &value
	}
	occurrence, err := sched.NextOccurrence(
		definition.Id,
		definition.Cron,
		definition.Timezone,
		afterUnixMs,
		lastOccurrenceID,
	)
	if err != nil {
		return witTypes.Err[witTypes.Option[types.Occurrence], string](err.Error())
	}
	if occurrence == nil {
		return noOccurrence()
	}
	return witTypes.Ok[witTypes.Option[types.Occurrence], string](
		witTypes.Some(types.Occurrence{
			Id:            occurrence.ID,
			ScheduledAtMs: occurrence.ScheduledAtMs,
		}),
	)
}

func noOccurrence() witTypes.Result[witTypes.Option[types.Occurrence], string] {
	return witTypes.Ok[witTypes.Option[types.Occurrence], string](
		witTypes.None[types.Occurrence](),
	)
}
